(function () {
  "use strict";

  var DATA_URL = "raw_results.json";
  var statusEl = document.getElementById("status");

  fetch(DATA_URL)
    .then(function (res) {
      if (!res.ok) throw new Error("HTTP " + res.status);
      return res.json();
    })
    .then(function (data) {
      statusEl.textContent = "Loaded " + DATA_URL + ".";
      statusEl.className = "ok";
      renderAll(data);
    })
    .catch(function (err) {
      statusEl.textContent =
        "Could not load " + DATA_URL + " (" + err.message + "). " +
        "This file is generated by benchmarks/runner.py and published alongside this page in CI. " +
        "If you're opening this file directly from disk, serve the repo over HTTP instead (e.g. `python -m http.server`) -- browsers block fetch() of local JSON over file://.";
      statusEl.className = "error";
    });

  function renderAll(data) {
    setupTabs();
    renderRoundTrip(data.round_trip);
    renderFaithfulness(data.faithfulness);
    renderLatency(data.latency);
    renderCost(data.cost_model);
    renderGrowth(data.growth);
  }

  // ---------- Tabs ----------
  function setupTabs() {
    var buttons = document.querySelectorAll(".tab-btn");
    buttons.forEach(function (btn) {
      btn.addEventListener("click", function () {
        buttons.forEach(function (b) { b.setAttribute("aria-selected", "false"); });
        document.querySelectorAll(".panel").forEach(function (p) { p.classList.remove("active"); });
        btn.setAttribute("aria-selected", "true");
        document.getElementById("panel-" + btn.dataset.panel).classList.add("active");
      });
    });
  }

  function fmtPct(n) { return n.toFixed(1) + "%"; }
  function el(tag, cls, text) {
    var e = document.createElement(tag);
    if (cls) e.className = cls;
    if (text !== undefined) e.textContent = text;
    return e;
  }

  // ---------- Round trip ----------
  function renderRoundTrip(rt) {
    var statsWrap = document.getElementById("roundtrip-stats");
    statsWrap.appendChild(statCard(fmtPct(rt.pct_ok), rt.n_ok + " / " + rt.n_total + " payloads byte-identical", rt.pct_ok === 100 ? "ok" : "warn"));
    statsWrap.appendChild(statCard(fmtPct(rt.storage_reduction_pct), "storage reduction (secondary metric, not blended with token/cost)", ""));
    statsWrap.appendChild(statCard(rt.total_original_bytes.toLocaleString(), "total original bytes", ""));
    statsWrap.appendChild(statCard(rt.total_encoded_bytes.toLocaleString(), "total encoded bytes", ""));

    var tbody = document.querySelector("#rt-table tbody");
    var filterSel = document.getElementById("rt-filter");

    function draw() {
      tbody.innerHTML = "";
      var mode = filterSel.value;
      rt.results.forEach(function (r) {
        if (mode === "fail" && r.ok) return;
        var tr = document.createElement("tr");
        if (!r.ok) tr.className = "fail";
        var delta = r.encoded_bytes - r.original_bytes;
        tr.appendChild(el("td", "", r.id));
        tr.appendChild(el("td", "num", r.original_bytes));
        tr.appendChild(el("td", "num", r.encoded_bytes));
        tr.appendChild(el("td", "num", (delta > 0 ? "+" : "") + delta));
        tr.appendChild(el("td", "", r.ok ? "yes" : "NO -- " + r.detail));
        tbody.appendChild(tr);
      });
    }
    filterSel.addEventListener("change", draw);
    draw();
  }

  function statCard(value, label, cls) {
    var card = el("div", "stat-card");
    card.appendChild(el("div", "value " + (cls || ""), value));
    card.appendChild(el("div", "label", label));
    return card;
  }

  // ---------- Faithfulness ----------
  function renderFaithfulness(faith) {
    var passSel = document.getElementById("faith-pass");
    Object.keys(faith).forEach(function (pass) {
      var opt = el("option", "", pass.replace(/_/g, " "));
      opt.value = pass;
      passSel.appendChild(opt);
    });

    var tbody = document.querySelector("#faith-table tbody");
    function cellClass(v) {
      if (v === null || v === undefined) return "";
      if (v >= 90) return "cell-good";
      if (v >= 50) return "cell-warn";
      return "cell-bad";
    }
    function draw() {
      tbody.innerHTML = "";
      var tiers = faith[passSel.value];
      Object.keys(tiers).forEach(function (tier) {
        var row = tiers[tier];
        var tr = document.createElement("tr");
        tr.appendChild(el("td", "", tier));
        ["numbers_retained_pct", "dates_retained_pct", "negations_retained_pct", "task_completion_retained_pct"].forEach(function (key) {
          var v = row[key];
          var text = v === null || v === undefined ? "n/a" : fmtPct(v);
          tr.appendChild(el("td", "num " + cellClass(v), text));
        });
        tbody.appendChild(tr);
      });
    }
    passSel.addEventListener("change", draw);
    draw();
  }

  // ---------- Latency ----------
  function renderLatency(lat) {
    var statsWrap = document.getElementById("latency-stats");
    statsWrap.appendChild(statCard(lat.warm_p50_ms + "ms", "warm p50 (n=" + lat.n_requests_warm + ")", ""));
    statsWrap.appendChild(statCard(lat.warm_p99_ms + "ms", "warm p99", ""));
    statsWrap.appendChild(statCard(lat.cold_p50_ms + "ms", "cold p50 (n=" + lat.n_requests_cold + ")", ""));
    statsWrap.appendChild(statCard(lat.cold_p99_ms + "ms", "cold p99", ""));
    document.getElementById("latency-note").textContent = lat.note;

    var canvas = document.getElementById("latency-chart");
    drawGroupedBars(canvas, {
      groups: ["p50", "p95", "p99"],
      series: [
        { label: "Warm", color: "#5eead4", values: [lat.warm_p50_ms, lat.warm_p95_ms, lat.warm_p99_ms] },
        { label: "Cold", color: "#f87171", values: [lat.cold_p50_ms, lat.cold_p95_ms, lat.cold_p99_ms] },
      ],
      unit: "ms",
    });
  }

  // ---------- Cost model ----------
  var STRATEGY_LABELS = {
    naive_loop: "Naive loop",
    naive_compression: "Naive compression",
    provider_caching_alone: "Provider caching alone",
    agent_gateway: "Agent Gateway",
  };
  var STRATEGY_ORDER = ["naive_loop", "naive_compression", "provider_caching_alone", "agent_gateway"];

  function renderCost(costModel) {
    var providerSel = document.getElementById("cost-provider");
    var canvas = document.getElementById("cost-chart");
    var tbody = document.querySelector("#cost-table tbody");
    var note = document.getElementById("cost-note");
    var shape = costModel._loop_shape;
    note.textContent =
      "Illustrative simulation, not observed billing. Loop shape: " + shape.n_turns + " turns, ~" +
      shape.avg_new_tokens_per_turn + " new input tokens/turn, ~" + shape.avg_output_tokens_per_turn +
      " output tokens/turn, compaction ceiling " + shape.compaction_ceiling_tokens + " tokens.";

    function draw() {
      var provider = providerSel.value;
      var costs = costModel[provider];
      var naive = costs.naive_loop;

      drawGroupedBars(canvas, {
        groups: STRATEGY_ORDER.map(function (k) { return STRATEGY_LABELS[k]; }),
        series: [{ label: "Cost", color: "#5eead4", values: STRATEGY_ORDER.map(function (k) { return costs[k]; }) }],
        unit: "$",
        singleSeriesColors: ["#f87171", "#fbbf24", "#60a5fa", "#4ade80"],
      });

      tbody.innerHTML = "";
      STRATEGY_ORDER.forEach(function (k) {
        var tr = document.createElement("tr");
        var pctOfNaive = ((costs[k] / naive) * 100).toFixed(1) + "% of naive";
        tr.appendChild(el("td", "", STRATEGY_LABELS[k]));
        tr.appendChild(el("td", "num", "$" + costs[k].toFixed(4)));
        tr.appendChild(el("td", "num", k === "naive_loop" ? "--" : pctOfNaive));
        tbody.appendChild(tr);
      });
    }
    providerSel.addEventListener("change", draw);
    draw();
  }

  // ---------- Growth curve ----------
  function renderGrowth(growth) {
    var runSel = document.getElementById("growth-run");
    growth.runs.forEach(function (r) {
      var opt = el("option", "", "Run " + r.run);
      opt.value = String(r.run);
      runSel.appendChild(opt);
    });
    document.getElementById("growth-avg-hitrate").textContent = fmtPct(growth.average_offload_hit_rate * 100);

    var statsWrap = document.getElementById("growth-stats");
    var canvas = document.getElementById("growth-chart");

    function draw() {
      var run = growth.runs.find(function (r) { return String(r.run) === runSel.value; }) || growth.runs[0];
      statsWrap.innerHTML = "";
      statsWrap.appendChild(statCard(run.naive_tokens_final_turn.toLocaleString(), "naive tokens, final turn", ""));
      statsWrap.appendChild(statCard(run.gateway_tokens_final_turn.toLocaleString(), "gateway tokens, final turn", "ok"));
      statsWrap.appendChild(statCard(fmtPct(run.offload_hit_rate * 100), "offload hit rate this run", "ok"));
      statsWrap.appendChild(statCard(String(run.total_artifacts_offloaded), "artifacts offloaded", ""));

      drawLineChart(canvas, {
        series: [
          { label: "Naive", color: "#f87171", values: run.naive_tokens_per_turn },
          { label: "Gateway", color: "#5eead4", values: run.gateway_tokens_per_turn },
        ],
      });
    }
    runSel.addEventListener("change", draw);
    draw();
  }

  // ---------- Canvas chart primitives (no external deps) ----------
  function devicePixelSetup(canvas) {
    var ctx = canvas.getContext("2d");
    var cssWidth = canvas.clientWidth || canvas.width;
    var cssHeight = canvas.width ? (canvas.height / canvas.width) * cssWidth : canvas.height;
    var dpr = window.devicePixelRatio || 1;
    canvas.width = cssWidth * dpr;
    canvas.height = cssHeight * dpr;
    canvas.style.height = cssHeight + "px";
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    return { ctx: ctx, width: cssWidth, height: cssHeight };
  }

  function drawGroupedBars(canvas, opts) {
    var setup = devicePixelSetup(canvas);
    var ctx = setup.ctx, W = setup.width, H = setup.height;
    ctx.clearRect(0, 0, W, H);

    var padL = 56, padB = 28, padT = 12, padR = 12;
    var plotW = W - padL - padR, plotH = H - padT - padB;
    var groups = opts.groups, series = opts.series;
    var allVals = [];
    series.forEach(function (s) { allVals = allVals.concat(s.values); });
    var maxVal = Math.max.apply(null, allVals) * 1.15 || 1;

    ctx.strokeStyle = "#232a3a";
    ctx.fillStyle = "#9aa4b8";
    ctx.font = "11px -apple-system, sans-serif";
    ctx.textAlign = "right";
    var gridLines = 4;
    for (var i = 0; i <= gridLines; i++) {
      var y = padT + plotH - (plotH * i) / gridLines;
      ctx.beginPath();
      ctx.moveTo(padL, y);
      ctx.lineTo(W - padR, y);
      ctx.stroke();
      var val = (maxVal * i) / gridLines;
      ctx.fillText((opts.unit === "$" ? "$" : "") + val.toFixed(opts.unit === "$" ? 2 : 0) + (opts.unit === "ms" ? "ms" : ""), padL - 6, y + 3);
    }

    var groupW = plotW / groups.length;
    var barGap = 6;
    var barsPerGroup = series.length;
    var barW = (groupW - barGap * (barsPerGroup + 1)) / barsPerGroup;

    groups.forEach(function (g, gi) {
      series.forEach(function (s, si) {
        var v = s.values[gi];
        var barH = (v / maxVal) * plotH;
        var x = padL + gi * groupW + barGap + si * (barW + barGap);
        var y = padT + plotH - barH;
        var color = opts.singleSeriesColors ? opts.singleSeriesColors[gi] : s.color;
        ctx.fillStyle = color;
        ctx.fillRect(x, y, barW, barH);
      });
      ctx.fillStyle = "#9aa4b8";
      ctx.textAlign = "center";
      ctx.font = "10px -apple-system, sans-serif";
      var label = g.length > 14 ? g.slice(0, 13) + "…" : g;
      ctx.fillText(label, padL + gi * groupW + groupW / 2, H - 8);
    });
  }

  function drawLineChart(canvas, opts) {
    var setup = devicePixelSetup(canvas);
    var ctx = setup.ctx, W = setup.width, H = setup.height;
    ctx.clearRect(0, 0, W, H);

    var padL = 56, padB = 28, padT = 12, padR = 12;
    var plotW = W - padL - padR, plotH = H - padT - padB;
    var series = opts.series;
    var n = series[0].values.length;
    var allVals = [];
    series.forEach(function (s) { allVals = allVals.concat(s.values); });
    var maxVal = Math.max.apply(null, allVals) * 1.1 || 1;

    ctx.strokeStyle = "#232a3a";
    ctx.fillStyle = "#9aa4b8";
    ctx.font = "11px -apple-system, sans-serif";
    ctx.textAlign = "right";
    var gridLines = 4;
    for (var i = 0; i <= gridLines; i++) {
      var y = padT + plotH - (plotH * i) / gridLines;
      ctx.beginPath();
      ctx.moveTo(padL, y);
      ctx.lineTo(W - padR, y);
      ctx.stroke();
      ctx.fillText(Math.round((maxVal * i) / gridLines), padL - 6, y + 3);
    }

    function xAt(idx) { return padL + (idx / (n - 1)) * plotW; }
    function yAt(val) { return padT + plotH - (val / maxVal) * plotH; }

    series.forEach(function (s) {
      ctx.strokeStyle = s.color;
      ctx.lineWidth = 2;
      ctx.beginPath();
      s.values.forEach(function (v, idx) {
        var x = xAt(idx), y = yAt(v);
        if (idx === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      });
      ctx.stroke();
    });

    ctx.fillStyle = "#9aa4b8";
    ctx.textAlign = "center";
    ctx.font = "10px -apple-system, sans-serif";
    ctx.fillText("turn 1", xAt(0), H - 8);
    ctx.fillText("turn " + n, xAt(n - 1), H - 8);
  }
})();
